import{_ as e,o as i,c as t,am as n}from"./chunks/framework.CiF4W93w.js";const h=JSON.parse('{"title":"分布式存储","description":"","frontmatter":{"title":"分布式存储","excerpt":"分布式存储","date":"2024-03-22 15:55:18","updated":"2024-03-22 15:55:18"},"headers":[],"relativePath":"架构篇/分布式系统/分布式存储.md","filePath":"架构篇/分布式系统/分布式存储.md","lastUpdated":null}'),o={name:"架构篇/分布式系统/分布式存储.md"};function s(p,a,l,r,d,c){return i(),t("div",null,[...a[0]||(a[0]=[n(`<h3 id="_1、minio" tabindex="-1">1、MinIO <a class="header-anchor" href="#_1、minio" aria-label="Permalink to &quot;1、MinIO&quot;">​</a></h3><p>MinIO是一个高性能、开源的对象存储服务，用于存储非结构化数据，如照片、视频、日志文件、备份和容器/虚拟机映像。</p><p>参考一下这个：</p><ul><li><a href="https://juejin.cn/post/7016528308451934221" target="_blank" rel="noreferrer">https://juejin.cn/post/7016528308451934221</a></li><li><a href="https://developer.aliyun.com/article/1002987" target="_blank" rel="noreferrer">https://developer.aliyun.com/article/1002987</a></li></ul><p>建议具体使用一下</p><p>一般是在我们项目中引入依赖，然后进行配置（客户端配置），通过设置访问密钥和私钥后，进行连接，可以进行上传文件操作，Minio 会提供一些公共 API 方法，我们一般会封装一个工具类，然后去使用他。</p><p>服务器的一种创建方式是通过dokcer 去拉取，然后创建容器启动，管理控制台后进行相关的配置。</p><hr><h4 id="服务器端配置" tabindex="-1">服务器端配置 <a class="header-anchor" href="#服务器端配置" aria-label="Permalink to &quot;服务器端配置&quot;">​</a></h4><p>拉取镜像</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker pull minio/minio</span></span></code></pre></div><p>创建一下挂载目录</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#创建存储，配置文件目录</span></span>
<span class="line"><span>mkdir -p /home/minio/{data,config}</span></span>
<span class="line"><span>#赋予目录权限</span></span>
<span class="line"><span>chmod 777 /home/minio/{data,config}</span></span></code></pre></div><p>启动容器</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker run -p 9000:9000 -p 9090:9090 --name minio -d --restart=always -e &quot;MINIO_ROOT_USER=minio&quot; -e &quot;MINIO_ROOT_PASSWORD=minio123&quot; -v /home/minio/data:/data -v /home/minio/config:/root/.minio minio/minio server /data --console-address &quot;:9090&quot;</span></span></code></pre></div><p>解析：</p><ul><li>-p:宿主端口：容器端口</li><li>--name：容器名称</li><li>--restart=always:设置docker启动时，容器跟随自启</li><li>-e &quot;MINIO_ACCESS_KEY=admin&quot;:设置minio的用户名</li><li>-e &quot;MINIO_SECRET_KEY=minio123&quot;：设置minio的密码</li><li>-v /home/minio/data:/data：挂载容器的存储目录到宿主</li><li>-v /home/minio/config:/root/.minio：挂载容器配置文件到宿主</li><li>/data --console-address &quot;:9090&quot;：固定 9090 端口访问minio的web控制台</li></ul><hr><p>通过 IP + 9090 端口，看是否能正常访问。</p><p>官方文档地址： <a href="https://www.minio.org.cn/docs/minio/container/index.html" target="_blank" rel="noreferrer">https://www.minio.org.cn/docs/minio/container/index.html</a></p><p>创建 minio 服务后，建议创建用户 → 创建用户组 → 创建公钥和私钥</p><p>这里找一个 minio 的 demo 项目看一下，主要还是总结一下相关流程，并知道如何通过 minio 进行文件上传下载操作。</p><p><a href="https://github.com/bm4578/SpringBoot/tree/main/SpringBoot-minio" target="_blank" rel="noreferrer">https://github.com/bm4578/SpringBoot/tree/main/SpringBoot-minio</a></p><p>（比较基础）</p><p>示例操作：</p><h3 id="_2、fastdfs" tabindex="-1">2、FastDFS <a class="header-anchor" href="#_2、fastdfs" aria-label="Permalink to &quot;2、FastDFS&quot;">​</a></h3><p>FastDFS是一个开源的轻量级分布式文件系统，它对文件进行管理，功能包括：文件存储、文件同步、文件访问（文件上传、文件下载）等，解决了大容量存储和负载均衡的问题。</p><ul><li><a href="https://cloud.tencent.com/developer/article/1466135" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/article/1466135</a></li></ul><h3 id="_3、oss" tabindex="-1">3、OSS <a class="header-anchor" href="#_3、oss" aria-label="Permalink to &quot;3、OSS&quot;">​</a></h3><p>略</p>`,30)])])}const u=e(o,[["render",s]]);export{h as __pageData,u as default};
